window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ef535cf306c21aa0"]={"versions": [{"id": "FIG-ef535cf306c21aa0", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methodik-Aktivitätsdiagramm (AUTOSAR Methodology Activity Diagram) im Kontext der Classic Platform zur Phase der Link-Time-Konfiguration („Link ECU Code during Link Time Configuration“). Das Diagramm spezifiziert den Integrations- und Bindevorgang zur Erzeugung der ausführbaren Binärdatei für ein Steuergerät.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Aktivität:</strong></p>\n<ul class=\"fig-list\"><li><code>Link ECU Code during Link Time Configuration</code>: Zentrale Binde-Aktivität (gelbes Pfeilsymbol/Prozessschritt).\n</li></ul>\n<p class=\"fig-p\"><strong>Artefakte (Dateien/Objektcode):</strong></p>\n<ul class=\"fig-list\"><li><code>Basic Software Module Object Code</code> (Dokumentensymbol, links oben): Eingangsartefakt mit Multiplizität <code>1..*</code> («input»).\n</li><li><code>BSW Module Configuration Data Object Code</code> (Dokumentensymbol, links Mitte): Eingangsartefakt mit Multiplizität <code>1..*</code> («input»).\n</li><li><code>ECU Object Code</code> (Dokumentensymbol, links unten): Eingangsartefakt mit Multiplizität <code>1..*</code> («input»).\n</li><li><code>ECU Executable</code> (Dokumentensymbol, rechts): Ausgangsartefakt mit Multiplizität <code>1</code> («output»).\n</li></ul>\n<p class=\"fig-p\"><strong>Werkzeuge:</strong></p>\n<ul class=\"fig-list\"><li><code>Linker</code> (Hammersymbol, rechts unten): Binde- und Übersetzungswerkzeug («used tool»).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Prozessschritt <code>Link ECU Code during Link Time Configuration</code> konsumiert mindestens ein kompiliertes Basissoftware-Modul (<code>Basic Software Module Object Code</code>, Kardinalität <code>1..*</code>), mindestens ein Objektcode-Artefakt aus Konfigurationsdaten (<code>BSW Module Configuration Data Object Code</code>, Kardinalität <code>1..*</code>) sowie mindestens ein weiteres ECU-Objektcode-Artefakt (<code>ECU Object Code</code>, Kardinalität <code>1..*</code>). Unter Verwendung des Werkzeugs <code>Linker</code> («used tool») werden alle referenzierten Objektcode-Module aufgelöst, statisch gebunden und zu genau einer lauffähigen Binärdatei <code>ECU Executable</code> («output», Kardinalität <code>1</code>) zusammengefügt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Schritt ist obligatorisch für Plattform- und ECU-Integratoren, wenn BSW-Module oder Konfigurationsanteile im Link-Time-Binding-Modus vorliegen. Er erfordert deterministische Linkerskripte sowie konsistente Symboltabellen zwischen den kompilierten BSW-Modulen, den Konfigurations-Objektdateien und dem restlichen Steuergeräte-Code (z. B. generierte SWC-Objekte oder MCAL-Treiber), um unaufgelöste Symbole zur Link-Zeit auszuschließen.</p>"}, {"id": "FIG-2543a08143a03ba7", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Methodik-Aktivitätsdiagramm (AUTOSAR Methodology Activity Diagram) im Kontext der Classic Platform zur Phase der Link-Time-Konfiguration („Link ECU Code during Link Time Configuration“). Das Diagramm spezifiziert den Integrations- und Bindevorgang zur Erzeugung der ausführbaren Binärdatei für ein Steuergerät.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\"><strong>Aktivität:</strong></p>\n<ul class=\"fig-list\"><li><code>Link ECU Code during Link Time Configuration</code>: Zentrale Binde-Aktivität (gelbes Pfeilsymbol/Prozessschritt).\n</li></ul>\n<p class=\"fig-p\"><strong>Artefakte (Dateien/Objektcode):</strong></p>\n<ul class=\"fig-list\"><li><code>Basic Software Module Object Code</code> (Dokumentensymbol, links oben): Eingangsartefakt mit Multiplizität <code>1..*</code> («input»).\n</li><li><code>BSW Module Configuration Data Object Code</code> (Dokumentensymbol, links Mitte): Eingangsartefakt mit Multiplizität <code>1..*</code> («input»).\n</li><li><code>ECU Object Code</code> (Dokumentensymbol, links unten): Eingangsartefakt mit Multiplizität <code>1..*</code> («input»).\n</li><li><code>ECU Executable</code> (Dokumentensymbol, rechts): Ausgangsartefakt mit Multiplizität <code>1</code> («output»).\n</li></ul>\n<p class=\"fig-p\"><strong>Werkzeuge:</strong></p>\n<ul class=\"fig-list\"><li><code>Linker</code> (Hammersymbol, rechts unten): Binde- und Übersetzungswerkzeug («used tool»).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Prozessschritt <code>Link ECU Code during Link Time Configuration</code> konsumiert mindestens ein kompiliertes Basissoftware-Modul (<code>Basic Software Module Object Code</code>, Kardinalität <code>1..*</code>), mindestens ein Objektcode-Artefakt aus Konfigurationsdaten (<code>BSW Module Configuration Data Object Code</code>, Kardinalität <code>1..*</code>) sowie mindestens ein weiteres ECU-Objektcode-Artefakt (<code>ECU Object Code</code>, Kardinalität <code>1..*</code>). Unter Verwendung des Werkzeugs <code>Linker</code> («used tool») werden alle referenzierten Objektcode-Module aufgelöst, statisch gebunden und zu genau einer lauffähigen Binärdatei <code>ECU Executable</code> («output», Kardinalität <code>1</code>) zusammengefügt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Schritt ist obligatorisch für Plattform- und ECU-Integratoren, wenn BSW-Module oder Konfigurationsanteile im Link-Time-Binding-Modus vorliegen. Er erfordert deterministische Linkerskripte sowie konsistente Symboltabellen zwischen den kompilierten BSW-Modulen, den Konfigurations-Objektdateien und dem restlichen Steuergeräte-Code (z. B. generierte SWC-Objekte oder MCAL-Treiber), um unaufgelöste Symbole zur Link-Zeit auszuschließen.</p>"}], "trans": [{"from": "FIG-ef535cf306c21aa0", "to": "FIG-2543a08143a03ba7", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
